python3 - <<'PY'
import json, pandas as pd, numpy as np
facts=json.load(open('facts.json'))
for f in facts:
    env={'pd':pd,'np':np}
    print('='*20, f['id'])
    print('SOURCE:', f['source'])
    for var,path in f['tables'].items():
        env[var]=pd.read_csv(path)
    try:
        out=eval(f['code'], env)
        print(out)
    except Exception as e:
        print('ERROR',type(e),e)
PY

